function getKlingAITranslation(key, lang) {
    if (klingaiTranslations[lang] && klingaiTranslations[lang][key]) {
        return klingaiTranslations[lang][key];
    }
    if (klingaiTranslations.en && klingaiTranslations.en[key]) {
        return klingaiTranslations.en[key];
    }
    return null;
}

function applyKlingAITranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.klingai.') || key.startsWith('review.common.'))) {
            const translation = getKlingAITranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    setTimeout(() => applyKlingAITranslations(e.detail.language), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        applyKlingAITranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
    });
} else {
    applyKlingAITranslations(window.i18n ? window.i18n.getCurrentLanguage() : 'en');
}


